struct VitalSyncRFResult { uint8_t predictedClass; float probabilities[3]; };
static inline VitalSyncRFResult vitalSyncModel2Predict(const float x[VITALSYNC_RF_N_FEATURES]) {
  float sums[3] = {0.0f, 0.0f, 0.0f};
  for (uint16_t t = 0; t < VITALSYNC_RF_N_TREES; ++t) {
    const uint32_t nodeBase = pgm_read_dword(&RF_TREE_NODE_OFFSET[t]);
    const uint32_t leafBase = pgm_read_dword(&RF_TREE_LEAF_OFFSET[t]);
    uint16_t node = 0;
    while (true) {
      const uint32_t gi = nodeBase + node;
      const uint8_t feature = pgm_read_byte(&RF_NODE_FEATURE[gi]);
      if (feature == 255) {
        const uint16_t localLeaf = pgm_read_word(&RF_NODE_LEFT[gi]);
        const uint32_t leaf = leafBase + localLeaf;
        sums[0] += pgm_read_byte(&RF_LEAF_PROBABILITIES[leaf * 3 + 0]) / 255.0f;
        sums[1] += pgm_read_byte(&RF_LEAF_PROBABILITIES[leaf * 3 + 1]) / 255.0f;
        sums[2] += pgm_read_byte(&RF_LEAF_PROBABILITIES[leaf * 3 + 2]) / 255.0f;
        break;
      }
      const uint16_t tid = pgm_read_word(&RF_NODE_THRESHOLD_INDEX[gi]);
      const uint32_t toff = pgm_read_dword(&RF_FEATURE_THRESHOLD_OFFSET[feature]);
      const float threshold = pgm_read_float(&RF_THRESHOLD_VALUES[toff + tid]);
      if (x[feature] <= threshold) node = pgm_read_word(&RF_NODE_LEFT[gi]);
      else node = pgm_read_word(&RF_NODE_RIGHT[gi]);
    }
  }
  VitalSyncRFResult result;
  uint8_t best = 0;
  for (uint8_t c = 0; c < 3; ++c) { result.probabilities[c] = sums[c] / VITALSYNC_RF_N_TREES; if (result.probabilities[c] > result.probabilities[best]) best = c; }
  result.predictedClass = best;
  return result;
}

static inline const char* vitalSyncModel2ClassName(uint8_t c) {
  switch (c) { case 0: return "CLEAN"; case 1: return "MILD_MOTION_CORRUPTION"; case 2: return "SEVERE_MOTION_CORRUPTION"; default: return "UNKNOWN"; }
}
